/* libtakeout.so exports only the C API (linux/src/takeout.h); everything else (the Kotlin
   runtime, SQLite) stays local, so it can't stand in for a library the host loads. (It once
   linked its own OpenSSL and curl, which Qt's TLS then called into and crashed; HTTP now goes
   through the host, PLAN.md L8.) */
{
  global: takeout_init; takeout_call; takeout_watch; takeout_unwatch;
          takeout_set_http; takeout_http_head; takeout_http_data; takeout_http_end;
  local: *;
};
